x%p %tIN+ %tIN- %tOUT 3T_Virtual%p PARAMS: Vos=#1 Ib=#3 Ioff=#5 Av=#7 BW=#9 Rin=#11 Rout=#13 Vpos=#15 Vneg=#17 

.SUBCKT 3T_Virtual%p in_pos in_neg out PARAMS: Av=500k BW=10Meg Rin=10Meg Rout=0 Vos=0 Ib=0 Ioff=0 Vpos=15 Vneg=-15 

* Input Stage: Rin, Ibias, Voffset
Vos in_pos 4 {Vos}
Ibias1 4 0 {Ib}
Ibias2 in_neg 0 {Ib}
Ios 4 in_neg {Ioff/2}
Rin 4 in_neg {Rin}

*Middle stage: Gain, frequency, voltage limiting
Bgain 0 6 I={v(4,in_neg)*Av/1meg }
R1 6 0 1meg
CP1 6 0 {Av/(2*pi*1meg*BW)}


Vpos 9 0 {Vpos}
Dlimit_pos 6 9 d1

Vneg 10 0 {Vneg}
Dlimit_neg 10 6 d1

.model d1 d(n=0.1) 

*Output stage: Buffer, output resistance 
E2 7 0 6 0 1
Rout 7 out {Rout}
.ends

x%p %tIN+ %tIN- %tVS+ %tVS- %tOUT 5T_Virtual%p params: Vos=#1 Ibias=#3 Ioffset=#5 Av=#7 BW=#9 SR=#11 CMRR=#13 Iomax=#15 Rin=#17 Rout=#19  

.subckt 5T_Virtual%p  In_p In_n Vpos Vneg Out params: Av=200k BW=20Meg CMRR=100
+SR=1Meg Rout=75 Iomax=25m Rin=100meg Vos=0.1m Ibias=1n Ioffset=1p
.param Rp1=1e6
.param Rs1=1e6
.param K_Is2a=sqrt(Av)/Rs1
.param K_Is2b=sqrt(Av)/Rp1
.param Cp1={Av/(2*pi*BW*Rp1)}
.param CMRR_lin=10**(CMRR/20)


Rin In_p In_n {Rin}
Bcm 4 3 V = { V(cm)/CMRR_lin}
Voff In_p 4 {Vos}
Ibias1 In_p 0 {Ibias}
Ibias2 In_n 0 {Ibias}
Ioffset In_p In_n {Ioffset/2}

Rcm1 In_p cm 10meg
Rcm2 In_n cm 10meg

BIs1a vref vs2a I = { K_Is2a*(V(3)-V(In_n)) }
Rs1 vs2a vref {Rs1}

BIs2b vref vs2b I = { K_Is2b*(V(vs2a)-v(vref)) }
Rp1 vs2b vref {Rp1}
VCp1sense vs2b vs2b_ 0
Cp1 vs2b_ vref {Cp1} 


D3 vs2b_ 8 Limit_Diode  
D4 8 vpos Limit_Diode  
B_SRp 8 vpos I={I(VCp1sense)- (Cp1*SR)}

D5 10 vs2b_ Limit_Diode
D6 Vneg 10 Limit_Diode
B_SRn Vneg 10 I={-1*I(VCp1sense)-(Cp1*SR)}  

DVpclip vs2b_ Vpos V_limit
DVnclip Vneg vs2b_ V_limit

Bout vref out_ I={(V(vs2b)-v(vref))/Rout}
Rout vref out_ {Rout}
Voutsense out_ out 0

D9 out 15 Limit_Diode  
D10 15 vpos Limit_Diode  
B_outp 15 vpos I={I(Voutsense)- Iomax}

D11 16 out Limit_Diode
D12 vneg 16 Limit_Diode
B_outn vneg 16 I={-1*I(Voutsense)-Iomax}  

R5 Vpos mid 1000000 
R6 mid Vneg 1000000 
Eref vref 0 mid 0 1

.MODEL Limit_Diode  D (IS= 1.0e-12)
.MODEL V_limit D(n=0.1)
.ends

a%p %%vd( %t2 %t1 ) %%vd( %t4 %t3 ) sq%p
.MODEL sq%p square(
+ cntl_array = [%f11:10:2]
+ freq_array = [%f12:10:2]
+ %v0?out_low = #1%v:%v;
+ %v2?out_high = #3%v:%v;
+ %v4?duty_cycle = #5%v:%v;
+ %v6?rise_time = #7%v:%v;
+ %v8?fall_time = #9%v:%v;)

x%p %tA %tB %tC %tshaft %tHa %tHb %tHc %tTe %ttheta %tEa %tEb %tEc BDCM_HALL_%p params: Ls=#1 Rs=#3 Ke=#5 Kt=#7 P=#9 J=#11 F=#13 ic_omega=#15 ic_theta=#17 

.subckt BDCM_HALL_%p    Va Vb Vc Omega HallA HallB HallC Te theta_out Ea_out Eb_out Ec_out params: Ls=1 Rs=1 Ke=1 Kt=1 P=1 J=1 F=1 ic_omega=0 ic_theta=0 
.param HallOutputLevel=5
.param ke_adj={ke/2}


RsA Va A1 {Rs}
LsA A1 Ea {Ls}
Ea Ea N value={V(omega)*V(k1)}

RsB Vb B1 {Rs}
LsB B1 Eb {Ls}
Eb Eb N value={V(omega)*V(k2)}

Rsc Vc c1 {Rs}
Lsc c1 Ec {Ls}
Ec Ec N value={V(omega)*V(k3)}

Gtheta_e 0 theta_electrical value={p*V(omega)}
C1 theta_electrical 0 1
.ic v(theta_electrical)={ic_theta}

Etheta theta 0 value={v(theta_electrical)/p}


ak1 %vd(theta_electrical 0) %vd(k1 0) pwlk1
.MODEL pwlk1 pwl(
+ x_array = [0 {pi/6} {5*pi/6} {7*pi/6} {11*pi/6} {2*pi}]
+ y_array = [0 {ke_adj} {ke_adj} {-ke_adj} {-ke_adj} 0]
+ wrap=true input_domain=0)

ak2 %vd(theta_electrical 0) %vd(k2 0) pwlk2
.MODEL pwlk2 pwl(
+ x_array = [0 {pi/2} {5*pi/6} {3*pi/2} {11*pi/6} {2*pi}]
+ y_array = [{-ke_adj} {-ke_adj} {ke_adj} {ke_adj} {-ke_adj} {-ke_adj}]
+ wrap=true input_domain=0)

ak3 %vd(theta_electrical 0) %vd(k3 0) pwlk3
.MODEL pwlk3 pwl(
+ x_array = [0 {pi/6} {pi/2} {7*pi/6} {3*pi/2} {2*pi}]
+ y_array = [{ke_adj} {ke_adj} {-ke_adj} {-ke_adj} {ke_adj} {ke_adj}]
+ wrap=true input_domain=0)


**Mechanical
Gtorque 0 omega_ value={v(k1)*I(Ea)*kt/ke+v(k2)*I(Eb)*kt/ke+v(k3)*I(Ec)*kt/ke}
VtorqueSense omega_ omega 0
Cinertia omega 0 {J}
.ic v(omega)={ic_omega}
Rfric omega 0 {1/F}


**Measurements
Etorque Te 0 value={I(VtorqueSense)}
Etheta_out theta_out 0 value={V(theta)}
E_Ea Ea_out 0 value={V(Ea,N)}
E_Eb Eb_out 0 value={V(Eb,N)}
E_Ec Ec_out 0 value={V(Ec,N)}

a1 hallA k1 k3 pcomp
a2 hallB k2 k1 pcomp
a3 hallC k3 k2 pcomp
.model pcomp precision_comparator(output_level={HallOutputLevel})



.ends

x%p %tvp %tvn %tomega %tTe %ttheta %tea DC_MACHINE_EXT%p Params: La=#1 Ra=#3 Ke=#5 Kt=#7 J=#9 B=#11 ic_omega=#13 ic_theta=#15

.subckt DC_MACHINE_EXT%p V+ V- omega torque theta_out Ea_out Params: La=5e-005 Ra=0.2 Ke=0.03 Kt=0.03 J=0.0001 B=1e-6 ic_omega=0 ic_theta=0

**Rotor (or armature)**
R1 V+ 2 {Ra}
L1 2 Ea {La}
Ebackemf Ea V- Value ={v(omega)*Ke}

**Mechanical side
Gtorque 0 omega_ value = {I(Ebackemf)*Kt}
Vtorquesense omega_ omega 0
CIntertia omega 0 {J}
.ic v(omega)={ic_omega}
Rfriction omega 0 {1/B}

**Measurements
EtorqueSignal torque 0 value={I(Vtorquesense)}
Gtheta 0 theta omega 0 1
Ctheta theta 0 1
.ic v(theta)={ic_theta}

Etheta theta_out 0 value={v(theta)}
Ea_out Ea_out 0 value={V(Ea,V-)}

.ends

x%p %tA %tB %tC %tomega %tTe IM_SQUIRREL_%p PARAMS: Lls=#1 Rs=#3  Llr=#5 Rr=#7 Lmag=#9 P=#11 J=#13 F=#15 ic_omega=#17

.subckt IM_SQUIRREL_%p Sa Sb Sc omega Te PARAMS: Lls=1 Rs=1 Llr=1 Rr=1 Lmag=1 P=1 J=1 F=1 ic_omega=0

**ABC/DQ stator-side
Ga Sa 0 value={I(V_Ids)}
Gb Sb 0 value={cos(0-2/3*pi)*I(V_Ids)-sin(0-2/3*pi)*I(V_Iqs)}
Gc Sc 0 value={cos(0+2/3*pi)*I(V_Ids)-sin(0+2/3*pi)*I(V_Iqs)}

Esd vsd 0 value={2/3 * (V(Sa) + V(Sb)*cos(0-2*pi/3) + V(Sc)*cos(0+2*pi/3))}
Esq vsq 0 value={-2/3 * (V(Sb)*sin(0-2*pi/3) + V(Sc)*sin(0+2*pi/3))}


**D axis circuit**
Rs_d vsd 1d {Rs}
V_Ids 1d 2d 0
Ls_d 2d 3d {Lls}
Lmag_d 3d 0 {Lmag}
Lr_d 3d 4d {Llr}
V_Idr 5d 4d 0
Rr_d 5d 6d {Rr}
EspeedVoltage_d 6d 0 value={-V(omega_e)*(Llr*I(V_Iqr)+Lmag*(I(V_Iqs) + I(V_Iqr)))}

**Q axis circuit
Rs_q vsq 1q {Rs}
V_Iqs 1q 2q 0
Ls_q 2q 3q {Lls}
Lmag_q 3q 0 {Lmag}
Lr_q 3q 4q {Llr}
V_Iqr 5q 4q 0
Rr_q 5q 6q {Rr}
EspeedVoltage_q 0 6q value={-V(omega_e)*(Llr*I(V_Idr)+Lmag*(I(V_Ids) + I(V_Idr)) )}



**Torque stage
Gtorque 0 omega_ value={3/2*p*Lmag*(I(V_Iqs)*I(V_Idr)-I(V_Ids)*I(V_Iqr))}
Vtorquesense omega_ omega 0
Cintertia omega 0 {J}
.ic v(omega)={ic_omega}
Rfric omega 0 {1/F}


**Measurements
Eomega_e omega_e 0 value={v(omega)*p}
Etorque Te 0 value={I(Vtorquesense)}



.ends

x%p %tA+ %tA- %tB+ %tB- %tomega %tTe %ttheta %tEa %tEb STEPPER_2P1W_%p PARAMS: L=#1 R=#3 angle=#5 Ke=#7 kt=#9 td=#11 J=#13 B=#15 Initial_omega=#17 Initial_theta=#19

.subckt STEPPER_2P1W_%p   Ph1+ Ph1- Ph2+ Ph2- omega torque theta_out Ea_out Eb_out PARAMS: L=1 R=1 angle=1 Ke=1 kt=1 td=1 J=1 B=1 Initial_omega=0 Initial_theta=0
.param N=180/2/angle

***Electrical***
Ra Ph1+ a1 {R}
La a1 a2 {L}
Ea a2 Ph1- value= {-1*Ke*v(omega)*sin(N*V(theta))} 

Rb Ph2+ b1 {R}
Lb b1 b2 {L}
Eb b2 Ph2- value= {Ke*v(omega)*sin(N*V(theta)+pi/2)} 

***Mechanical***
Gta 0 omega_ value={-1*Kt*I(Ea)*sin(N*V(theta))} 
Gtb 0 omega_ value={Kt*I(Eb)*sin(N*V(theta)+pi/2)} 
Gtd 0 omega_ value={-1*td*sin(4*N*V(theta))}

Vtorquesense omega_ omega 0
Rfric omega 0 {1/B}
Ciner omega 0 {J}
.ic v(omega)={Initial_omega}

Gint 0 theta value={v(omega)}
C1 theta 0 1
.ic v(theta)={Initial_theta}

**theta calculation and measurements**
Etorque torque 0 value={I(Vtorquesense)}
Etheta_out theta_out 0 value={v(theta)}
Ea_out Ea_out 0 value={V(a2,Ph1-)}
Eb_out Eb_out 0 value={V(b2,Ph2-)}

.ends

x%p %tA1+ %tA1- %tA2+ %tA2- %tB1+ %tB1- %tB2+ %tB2- %tshaft %tTe %ttheta %tEa %tEb STEPPER_2P2W_%p PARAMS: L=#1 R=#3 step=#5 Ke=#7 kt=#9 td=#11 J=#13 B=#15 Initial_omega=#17 Initial_theta=#19

.subckt STEPPER_2P2W_%p   A1+ A1- A2+ A2- B1+ B1- B2+ B2- omega te theta_out Ea_out Eb_out PARAMS: L=1 R=1 Step=1 Ke=1 Kt=1 td=1 J=1 B=1 Initial_omega=0 Initial_theta=0 
.param N=180/2/step

***Electrical***
Ra1 A1+ 100 {R}
La1 100 200 {L}
Ea1 200 A1- value= {-1*Ke*v(omega)*sin(N*V(theta))} 

Ra2 A2+ 1002 {R}
La2 2002 1002 {L}
Ea2 2002 A2- value= {-1*Ke*v(omega)*sin(N*V(theta))} 

k1 La1 La2 1

Rb1 B1+ 10 {R}
Lb1 10 20 {L}
Eb1 20 B1- value= {Ke*v(omega)*sin(N*V(theta)+pi/2)} 

Rb2 B2+ 102 {R}
Lb2 202 102 {L}
Eb2 202 B2- value= {Ke*v(omega)*sin(N*V(theta)+pi/2)} 

k2 Lb1 Lb2 1

***Mechanical***
Gta1 0 omega_ value={-1*Kt*I(Ea1)*sin(N*V(theta))}
Gta2 0 omega_ value={Kt*I(Ea2)*sin(N*V(theta))}

Gtb1 0 omega_ value={Kt*I(Eb1)*sin(N*V(theta)+pi/2)}
Gtb2 0 omega_ value={-1*Kt*I(Eb2)*sin(N*V(theta)+pi/2)}

Gtd 0 omega_ value={-1*td*sin(4*N*V(theta))}

Vtorquesense omega_ omega 0

Rfric omega 0 {1/B}
Ciner omega 0 {J}
.ic v(omega)={Initial_omega}

Gint 0 theta value={v(omega)}
C1 theta 0 1
.ic v(theta)={Initial_theta}

**measurements
Etorque te 0 value={I(Vtorquesense)}
Etheta_out theta_out 0 value={V(theta)}
Ea_out Ea_out 0 value={V(200,A1-)}
Eb_out Eb_out 0 value={V(202,B2-)}

.ends

x%p %tA %tB %tC %tshaft %tTe %ttheta PMSM_%p PARAMS: Ld=#1 Lq=#3 Rs=#5 PM_flux=#7 P=#9 J=#11 F=#13 Initial_omega=#15 Initial_theta=#17

.subckt PMSM_%p VA VB VC omega torque theta_out PARAMS: Ld=1 Lq=1 Rs=1 PM_flux=1 P=1 J=1 F=1 Initial_omega=0 Initial_theta=0


**ABC-to-DQ transformer begin***
Ga Va 0 value={cos(v(theta_e))*I(Ld)-sin(v(theta_e))*I(Lq)}
Gb Vb 0 value={cos(v(theta_e)-2/3*pi)*I(Ld)-sin(v(theta_e)-2/3*pi)*I(Lq)}
Gc Vc 0 value={cos(v(theta_e)+2/3*pi)*I(Ld)-sin(v(theta_e)+2/3*pi)*I(Lq)}

Ed vd 0 value={2/3 * (V(Va)*cos(v(theta_e)) + V(Vb)*cos(v(theta_e)-2*pi/3) + V(Vc)*cos(v(theta_e)+2*pi/3))}
Eq vq 0 value={-2/3 * (V(Va)*sin(v(theta_e)) + V(Vb)*sin(v(theta_e)-2*pi/3) + V(Vc)*sin(v(theta_e)+2*pi/3))}

**ABC-to-DQ transformer end**
**D axis circuit
Rs_d vd 1d {Rs}
Ld 1d 2d {Ld}
EspeedVoltage_d 0 2d value={p*v(omega)*Lq*I(Lq)}

**Q axis circuit**
Rs_q vq 1q {Rs}
Lq 1q 2q {Lq}
EspeedVoltage_q 2q 0 value={p*v(omega)*(Ld*I(Ld)+PM_flux)}


**Torque stage
Gtorque 0 omega_ value={3/2*p*(((Ld*I(Ld)+PM_flux))*I(Lq) - Lq*I(Lq)*I(Ld))}
Vtorquesense omega_ omega 0
Cintertia omega 0 {J}
.ic v(omega)={Initial_omega}

Rfric omega 0 {1/F}


Gtheta 0 theta value={V(omega)}
Ctheta 0 theta 1
.ic v(theta)={Initial_theta}
Etheta_e theta_e 0 value={v(theta)*p}

***measurements
Etorque torque 0 value={I(Vtorquesense)} 
Etheta_out theta_out 0 value={v(theta)}

.ends

x%p %t1 %t2 GEARS_%p Params: ratio=#1

.subckt GEARS_%p  Win Wout PARAMS: ratio=1
E1 Wout 0 value={V(Win)*ratio}
G1 Win 0 value={-1*I(E1)*ratio}
.ends

x%p %tw_in %tw_out %tcos+ %tcos- %tsin+ %tsin- RESOLVER_%p Params: ref_amplitude=#1 ref_frequency=#3 initial_theta=#5

.subckt RESOLVER_%p  omega_in omega_out cos+ cos- sin+ sin- Params: ref_amplitude=1 ref_frequency=1 initial_theta=0
.mergenodes omega_in omega_out


Vref ref 0 sin(0 {ref_amplitude} {ref_frequency})
Ecos cos+ cos- value={v(ref)*cos(v(theta))}
Esin sin+ sin- value={v(ref)*sin(v(theta))}


Gtheta 0 theta value={v(omega_in)}
Cint theta 0 1

.ic v(theta)={initial_theta}

.ends
